def resolve(path, cwd, links):
    if links is None:
        links = {}

    if not path.startswith('/'):
        path = cwd.rstrip('/') + '/' + path

    parts = path.split('/')

    current = []
    link_count = 0
    i = 0

    while i < len(parts):
        component = parts[i]

        if component == '' or component == '.':
            i += 1
            continue

        if component == '..':
            if current:
                current.pop()
            i += 1
            continue

        current.append(component)

        current_path = '/' + '/'.join(current)

        if current_path in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current_path]

            remaining = parts[i + 1:]

            if target.startswith('/'):
                current = []
                new_parts = target.split('/')
            else:
                if current:
                    current.pop()
                parent_path = '/' + '/'.join(current) if current else '/'
                new_parts = (parent_path.rstrip('/') + '/' + target).split('/')
                current = []

            parts = new_parts + remaining
            i = 0
        else:
            i += 1

    result = '/' + '/'.join(current)
    if result == '/':
        return '/'
    return result.rstrip('/')

